    values=dict(BEFORE=gap(b['minimum_sample_gap_m']),AFTER=gap(c['minimum_sample_gap_m']),MAX=gap(c['maximum_patch_sample_gap_m']),MEDIAN=gap(c['median_patch_gap_m']),AREA=f"{c['contact_area_mm2']:.2f}",REGRESSION=f"{-metrics['relative_error_reduction']*100:.2f}",COVERAGE=f"{c['contact_area_fraction']*100:.0f}",BAR=str(100*c['minimum_sample_gap_m']/b['minimum_sample_gap_m']),TIMING=timing,TABLE=table,NME0=f"{metrics['rows'][0]['joint_nme']:.6f}",NME1=f"{metrics['rows'][1]['joint_nme']:.6f}",MODEL=html.escape(vlm['model_actual']),REASONS=reasons,SHA=contact['artifact_sha256'])
    for key,value in values.items():page=page.replace('@@'+key+'@@',value)
    (o/'index.html').write_text(page)
